import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Effective_DateInputs */

const en_effective_date = /** @type {(inputs: Effective_DateInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Effective Date: October 11, 2026 • Version 2.4`)
};

const vi_effective_date = /** @type {(inputs: Effective_DateInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Ngày có hiệu lực: 11 Tháng 10, 2026 • Phiên bản 2.4`)
};

/**
* | output |
* | --- |
* | "Effective Date: October 11, 2026 • Version 2.4" |
*
* @param {Effective_DateInputs} inputs
* @param {{ locale?: "en" | "vi" }} options
* @returns {LocalizedString}
*/
export const effective_date = /** @type {((inputs?: Effective_DateInputs, options?: { locale?: "en" | "vi" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Effective_DateInputs, { locale?: "en" | "vi" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "vi") return vi_effective_date(inputs)
	return en_effective_date(inputs)
});